begin;
update public.questions set subject = 'Environment & Ecology', topic = 'Protected Areas & Wildlife Protection', type = 'statement_based', difficulty = 'medium', body = 'Chhari-Dhand in Gujarat was designated a Ramsar site on World Wetlands Day, 2 February 2026. Consider the following statements:', body_hi = 'गुजरात के छारी-ढंड को 2 फ़रवरी 2026, विश्व आर्द्रभूमि दिवस, पर रामसर स्थल घोषित किया गया। निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Statements 1 and 2 are correct. Chhari-Dhand (''dhand'' is the Kutchi word for a shallow, seasonal lake) fills in good monsoons between the Banni grassland and the salt flats of the Rann, drawing cranes, flamingos and other migratory birds, and is protected as a conservation reserve. Banni, a vast low grassland on the northern edge of Kutch, has long been the grazing land of the Maldharis, pastoralists known for the Banni buffalo and the Kankrej cattle -- a living example of the rangelands that the UN has made the theme of 2026, and a proposed future home for cheetahs. Statement 3 is wrong: a Ramsar listing is an international recognition and commitment to ''wise use''; legal protection comes from Indian law -- the Wild Life (Protection) Act, the Environment (Protection) Act or the Wetlands (Conservation and Management) Rules, 2017 -- which is why a Ramsar site can lie partly outside any protected area. With Chhari-Dhand and Patna Bird Sanctuary, India''s tally reached 98 sites.', explanation_hi = 'कथन 1 और 2 सही हैं। छारी-ढंड (‘ढंड’ कच्छी में उथली, मौसमी झील को कहते हैं) अच्छे मानसून में बन्नी घास के मैदान और रण के लवणीय मैदानों के बीच भर जाता है, सारस, राजहंस तथा अन्य प्रवासी पक्षियों को आकर्षित करता है, और संरक्षण आरक्षित क्षेत्र के रूप में संरक्षित है। कच्छ के उत्तरी किनारे का विशाल, निचला घास का मैदान बन्नी लंबे समय से मालधारियों की चरागाह रहा है, जो बन्नी भैंस और कांकरेज गाय के लिए जाने जाने वाले पशुपालक हैं -- यह उन चरागाहों का जीवित उदाहरण है जिन्हें संयुक्त राष्ट्र ने 2026 का विषय बनाया है, और चीतों का एक प्रस्तावित भावी घर भी। कथन 3 ग़लत है: रामसर सूची एक अंतरराष्ट्रीय मान्यता और ‘विवेकपूर्ण उपयोग’ की प्रतिबद्धता है; विधिक संरक्षण भारतीय क़ानून -- वन्यजीव (संरक्षण) अधिनियम, पर्यावरण (संरक्षण) अधिनियम या आर्द्रभूमि (संरक्षण और प्रबंधन) नियम, 2017 -- से आता है, इसीलिए कोई रामसर स्थल आंशिक रूप से किसी संरक्षित क्षेत्र के बाहर भी हो सकता है। छारी-ढंड और पटना पक्षी अभयारण्य के साथ भारत के स्थलों की संख्या 98 पहुँची।', concept_group_id = 'ca-t1-env-chhari-dhand-conservation-reserve', source_citation = 'Wetlands (Conservation and Management) Rules, 2017; Ministry of Environment, Forest and Climate Change, release on World Wetlands Day (2 February 2026); Government of Gujarat, Banni grassland.', question_data = '{"statements": ["Chhari-Dhand is a seasonal wetland on the edge of the Banni grasslands of Kutch.", "The Banni grasslands are grazed by the herds of the Maldhari pastoralists.", "Designation as a Ramsar site by itself gives a wetland the legal status of a protected area under Indian law."], "statements_hi": ["छारी-ढंड कच्छ के बन्नी घास के मैदानों के किनारे स्थित एक मौसमी आर्द्रभूमि है।", "बन्नी घास के मैदानों में मालधारी पशुपालकों के पशु चरते हैं।", "रामसर स्थल घोषित होना अपने आप किसी आर्द्रभूमि को भारतीय क़ानून के अंतर्गत संरक्षित क्षेत्र का विधिक दर्जा दे देता है।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true, "craft": "linkage", "ca_window": "2026-Q1"}'::jsonb, options = '[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "1, 2 and 3", "body_hi": "1, 2 और 3", "isCorrect": false}, {"id": "d", "body": "1 and 2 only", "body_hi": "केवल 1 और 2", "isCorrect": true}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'ca-t1-env-chhari-dhand-conservation-reserve' returning concept_group_id;
update public.questions set subject = 'Environment & Ecology', topic = 'International Conventions & Organisations', type = 'mcq', difficulty = 'easy', body = 'Patna Bird Sanctuary, designated one of India''s two new Ramsar sites on World Wetlands Day 2026, is located in:', body_hi = 'विश्व आर्द्रभूमि दिवस 2026 पर भारत के दो नए रामसर स्थलों में से एक घोषित पटना पक्षी अभयारण्य स्थित है:', explanation = 'Patna Bird Sanctuary is a small lake-and-marsh sanctuary near the village of Patna in Etah district of Uttar Pradesh, a wintering ground for ducks, geese and other waterbirds; its name is what makes Bihar''s capital a tempting wrong answer. It was designated together with Chhari-Dhand in Kutch on 2 February 2026, the day the Convention marks its signing at Ramsar, Iran, in 1971. Bihar''s own Ramsar sites, such as Kanwar Jheel in Begusarai, are elsewhere; Jharkhand and Madhya Pradesh have no site called Patna.', explanation_hi = 'पटना पक्षी अभयारण्य उत्तर प्रदेश के एटा ज़िले में पटना गाँव के पास झील और दलदल वाला एक छोटा अभयारण्य है, जो बत्तखों, हंसों और अन्य जलपक्षियों का शीतकालीन ठिकाना है; इसका नाम ही बिहार की राजधानी को एक लुभावना ग़लत उत्तर बनाता है। इसे 2 फ़रवरी 2026 को, जिस दिन 1971 में ईरान के रामसर में अभिसमय पर हस्ताक्षर हुए थे, कच्छ के छारी-ढंड के साथ घोषित किया गया। बिहार के अपने रामसर स्थल, जैसे बेगूसराय का कांवर झील, कहीं और हैं; झारखंड और मध्य प्रदेश में पटना नाम का कोई स्थल नहीं है।', concept_group_id = 'ca-t1-env-patna-bird-sanctuary-etah', source_citation = 'Ministry of Environment, Forest and Climate Change, release on new Ramsar sites (2 February 2026); Ramsar Sites Information Service.', question_data = '{"craft": "recall", "ca_window": "2026-Q1"}'::jsonb, options = '[{"id": "a", "body": "Bihar", "body_hi": "बिहार", "isCorrect": false}, {"id": "b", "body": "Uttar Pradesh", "body_hi": "उत्तर प्रदेश", "isCorrect": true}, {"id": "c", "body": "Jharkhand", "body_hi": "झारखंड", "isCorrect": false}, {"id": "d", "body": "Madhya Pradesh", "body_hi": "मध्य प्रदेश", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'ca-t1-env-patna-bird-sanctuary-etah' returning concept_group_id;
update public.questions set subject = 'Environment & Ecology', topic = 'Climate Science & Mitigation', type = 'statement_based', difficulty = 'medium', body = 'The Union Budget 2026-27 earmarked ₹20,000 crore over five years for carbon capture, utilisation and storage (CCUS). Consider the following statements:', body_hi = 'केंद्रीय बजट 2026-27 ने कार्बन अभिग्रहण, उपयोग और भंडारण (सीसीयूएस) के लिए पाँच वर्षों में ₹20,000 करोड़ निर्धारित किए। निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'All four statements are correct. Captured CO2 can be stored or used: injected into oil reservoirs it raises output while some of it remains trapped; injected into reactive rocks such as the Deccan basalts it mineralises into carbonates within a few years; pumped into deep saline aquifers, porous rock filled with brine below a sealing cap rock, it can be held for millennia; and it is a feedstock for urea (which India already makes from CO2 and ammonia), methanol, polymers and building materials. Capture works economically only at large, concentrated point sources, so the Budget mission is aimed at hard-to-abate industries -- steel, cement, refineries, chemicals -- where electricity from renewables cannot easily cut process emissions; emissions from millions of vehicles and homes are cut instead by electrification and efficiency.', explanation_hi = 'चारों कथन सही हैं। अभिगृहीत CO2 का भंडारण या उपयोग हो सकता है: तेल भंडारों में डालने पर वह उत्पादन बढ़ाती है और उसका कुछ भाग फँसा रहता है; दक्कन के बेसाल्ट जैसी अभिक्रियाशील चट्टानों में डालने पर कुछ वर्षों में कार्बोनेट में बदल जाती है; गहरे लवणीय जलभृतों में, यानी किसी अभेद्य आवरण-चट्टान के नीचे खारे पानी से भरी सरंध्र चट्टान में, पंप करने पर हज़ारों वर्ष रोकी जा सकती है; और वह यूरिया (जिसे भारत पहले से CO2 और अमोनिया से बनाता है), मेथनॉल, बहुलक और निर्माण-सामग्री का कच्चा माल है। अभिग्रहण आर्थिक रूप से केवल बड़े, सघन बिंदु-स्रोतों पर काम करता है, इसलिए बजट का मिशन इस्पात, सीमेंट, रिफ़ाइनरी और रसायन जैसे कठिन-से-घटने वाले उद्योगों के लिए है, जहाँ नवीकरणीय बिजली प्रक्रिया-उत्सर्जन आसानी से नहीं घटा सकती; लाखों वाहनों और घरों का उत्सर्जन विद्युतीकरण और दक्षता से घटाया जाता है।', concept_group_id = 'ca-t1-env-ccus-mission-eor-mineralisation', source_citation = 'Union Budget 2026-27, Budget Speech (1 February 2026); NITI Aayog, Carbon Capture, Utilization and Storage (CCUS) Policy Framework and its Deployment Mechanism in India (2022).', question_data = '{"statements": ["Captured carbon dioxide can serve as a raw material for products such as urea and methanol.", "In carbon mineralisation, carbon dioxide reacts with rocks such as basalt to form stable carbonate minerals.", "Captured carbon dioxide can also be stored permanently in deep saline aquifers.", "In enhanced oil recovery, captured carbon dioxide is injected into ageing oil fields to push out more oil, and part of it stays underground."], "statements_hi": ["अभिगृहीत कार्बन डाइऑक्साइड यूरिया और मेथनॉल जैसे उत्पादों के लिए कच्चे माल का काम कर सकती है।", "कार्बन खनिजीकरण में कार्बन डाइऑक्साइड बेसाल्ट जैसी चट्टानों से अभिक्रिया करके स्थिर कार्बोनेट खनिज बनाती है।", "अभिगृहीत कार्बन डाइऑक्साइड को गहरे लवणीय जलभृतों में स्थायी रूप से भंडारित भी किया जा सकता है।", "संवर्धित तेल पुनर्प्राप्ति में अभिगृहीत कार्बन डाइऑक्साइड को पुराने तेल क्षेत्रों में डाला जाता है ताकि अधिक तेल निकले, और उसका एक भाग भूमिगत रह जाता है।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true, "craft": "application", "ca_window": "2026-Q1"}'::jsonb, options = '[{"id": "a", "body": "1 and 2 only", "body_hi": "केवल 1 और 2", "isCorrect": false}, {"id": "b", "body": "1, 2, 3 and 4", "body_hi": "1, 2, 3 और 4", "isCorrect": true}, {"id": "c", "body": "1, 3 and 4 only", "body_hi": "केवल 1, 3 और 4", "isCorrect": false}, {"id": "d", "body": "2, 3 and 4 only", "body_hi": "केवल 2, 3 और 4", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'ca-t1-env-ccus-mission-eor-mineralisation' returning concept_group_id;
update public.questions set subject = 'Environment & Ecology', topic = 'International Conventions & Organisations', type = 'statement_based', difficulty = 'hard', body = 'The Agreement on Marine Biological Diversity of Areas beyond National Jurisdiction (the ''High Seas Treaty'') entered into force in January 2026. Consider the following statements:', body_hi = 'राष्ट्रीय अधिकार-क्षेत्र से परे क्षेत्रों की समुद्री जैव-विविधता पर समझौता (‘उच्च सागर संधि’) जनवरी 2026 में लागू हुआ। निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Only statement 1 is correct. The treaty, adopted in 2023 under the UN Convention on the Law of the Sea, reached its sixtieth ratification in September 2025 and entered into force on 17 January 2026; its first Conference of the Parties must meet within a year. It covers four packages for the high seas and the deep seabed beyond national jurisdiction: the fair sharing of benefits from marine genetic resources and their digital sequence information, area-based tools including marine protected areas, environmental impact assessments, and capacity building and technology transfer. Statement 2 is wrong: the treaty applies only beyond national jurisdiction and expressly does not touch the rights of coastal States; an EEZ cannot extend beyond 200 nautical miles under UNCLOS, though a State may claim an extended continental shelf through the Commission on the Limits of the Continental Shelf.', explanation_hi = 'केवल कथन 1 सही है। समुद्री विधि पर संयुक्त राष्ट्र अभिसमय के अंतर्गत 2023 में अपनाई गई संधि को सितंबर 2025 में साठवाँ अनुसमर्थन मिला और वह 17 जनवरी 2026 को लागू हुई; इसके पक्षकारों का पहला सम्मेलन एक वर्ष के भीतर होना है। यह राष्ट्रीय अधिकार-क्षेत्र से परे उच्च सागरों और गहरे समुद्र-तल के लिए चार पैकेज समेटती है: समुद्री आनुवंशिक संसाधनों और उनकी डिजिटल अनुक्रम सूचना से लाभों का न्यायसंगत बँटवारा, समुद्री संरक्षित क्षेत्रों सहित क्षेत्र-आधारित उपकरण, पर्यावरणीय प्रभाव आकलन, और क्षमता-निर्माण तथा प्रौद्योगिकी हस्तांतरण। कथन 2 ग़लत है: संधि केवल राष्ट्रीय अधिकार-क्षेत्र से परे लागू होती है और तटीय राज्यों के अधिकारों को स्पष्ट रूप से नहीं छूती; यूएनक्लॉस के अंतर्गत अनन्य आर्थिक क्षेत्र 200 समुद्री मील से आगे नहीं बढ़ सकता, यद्यपि कोई राज्य महाद्वीपीय मग्नतट की सीमाओं पर आयोग के माध्यम से विस्तारित महाद्वीपीय मग्नतट का दावा कर सकता है।', concept_group_id = 'ca-t1-env-bbnj-entry-into-force-120-days', source_citation = 'Agreement under UNCLOS on the Conservation and Sustainable Use of Marine Biological Diversity of Areas beyond National Jurisdiction (2023), Articles 68 and 47; UNCLOS, Articles 57 and 76.', question_data = '{"statements": ["It entered into force 120 days after the sixtieth instrument of ratification or accession was deposited.", "It allows coastal States to extend their exclusive economic zones beyond 200 nautical miles."], "statements_hi": ["यह अनुसमर्थन या अधिमिलन का साठवाँ लिखत जमा होने के 120 दिन बाद लागू हुआ।", "यह तटीय राज्यों को अपने अनन्य आर्थिक क्षेत्र 200 समुद्री मील से आगे बढ़ाने की अनुमति देता है।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true, "craft": "precision", "ca_window": "2026-Q1"}'::jsonb, options = '[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": true}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'ca-t1-env-bbnj-entry-into-force-120-days' returning concept_group_id;
update public.questions set subject = 'Environment & Ecology', topic = 'Protected Areas & Wildlife Protection', type = 'statement_based', difficulty = 'medium', body = 'Project Cheetah received a new batch of animals in February 2026. Consider the following statements:', body_hi = 'फ़रवरी 2026 में प्रोजेक्ट चीता को जानवरों का एक नया दल मिला। निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Only statement 1 is correct. The first cheetahs came from Namibia in 2022 and the second batch from South Africa in 2023; the nine cheetahs released into quarantine at Kuno National Park on 28 February 2026 came from Botswana, flown in with the Air Force''s help -- the project''s third international transfer. Statement 2 is wrong: Gandhi Sagar Wildlife Sanctuary, which received cheetahs in 2025, lies in Madhya Pradesh, on the Chambal in Mandsaur and Neemuch districts, like Kuno; the Banni grasslands of Gujarat and Nauradehi in Madhya Pradesh are being prepared as future sites. Statement 3 is wrong: the cheetah as a species is listed as Vulnerable; only the Asiatic subspecies, which survives in Iran, is Critically Endangered.', explanation_hi = 'केवल कथन 1 सही है। पहले चीते 2022 में नामीबिया से और दूसरा दल 2023 में दक्षिण अफ़्रीका से आया; 28 फ़रवरी 2026 को कूनो राष्ट्रीय उद्यान में संगरोध बाड़ों में छोड़े गए नौ चीते बोत्सवाना से वायु सेना की सहायता से लाए गए -- यह परियोजना का तीसरा अंतरराष्ट्रीय स्थानांतरण था। कथन 2 ग़लत है: 2025 में चीते पाने वाला गांधी सागर वन्यजीव अभयारण्य कूनो की तरह मध्य प्रदेश में, मंदसौर और नीमच ज़िलों में चंबल पर स्थित है; गुजरात के बन्नी घास के मैदान और मध्य प्रदेश का नौरादेही भावी स्थलों के रूप में तैयार किए जा रहे हैं। कथन 3 ग़लत है: प्रजाति के रूप में चीता सुभेद्य (वल्नरेबल) सूचीबद्ध है; केवल एशियाई उप-प्रजाति, जो ईरान में बची है, गंभीर रूप से संकटग्रस्त है।', concept_group_id = 'ca-t1-env-cheetah-botswana-gandhi-sagar', source_citation = 'Ministry of Environment, Forest and Climate Change and National Tiger Conservation Authority, releases on Project Cheetah (February 2026); IUCN Red List, Acinonyx jubatus.', question_data = '{"statements": ["The batch of cheetahs that reached Kuno in February 2026 came from Botswana.", "Gandhi Sagar Wildlife Sanctuary, which became the project''s second home for cheetahs, is in Rajasthan.", "The African cheetah is classified as Endangered on the IUCN Red List."], "statements_hi": ["फ़रवरी 2026 में कूनो पहुँचे चीतों का दल बोत्सवाना से आया था।", "परियोजना के चीतों का दूसरा घर बना गांधी सागर वन्यजीव अभयारण्य राजस्थान में है।", "अफ़्रीकी चीता आईयूसीएन रेड लिस्ट में संकटग्रस्त (एंडेंजर्ड) श्रेणी में है।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true, "craft": "precision", "ca_window": "2026-Q1"}'::jsonb, options = '[{"id": "a", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "b", "body": "1 and 2 only", "body_hi": "केवल 1 और 2", "isCorrect": false}, {"id": "c", "body": "1 and 3 only", "body_hi": "केवल 1 और 3", "isCorrect": false}, {"id": "d", "body": "1 only", "body_hi": "केवल 1", "isCorrect": true}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'ca-t1-env-cheetah-botswana-gandhi-sagar' returning concept_group_id;
update public.questions set subject = 'Environment & Ecology', topic = 'Climate Science & Mitigation', type = 'statement_based', difficulty = 'hard', body = 'In February 2026 district cooling was discussed as a way of meeting the fast-growing demand for cooling in Indian cities. Consider the following statements:', body_hi = 'फ़रवरी 2026 में भारतीय शहरों में शीतलन की तेज़ी से बढ़ती माँग पूरी करने के एक उपाय के रूप में डिस्ट्रिक्ट कूलिंग पर चर्चा हुई। निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'All four statements are correct. A district cooling network runs large, efficient chillers at one plant and sends chilled water through insulated pipes to offices, malls or housing, cutting electricity use and peak load compared with thousands of separate units; it suits dense new developments such as GIFT City, which has one. India was among the first countries to prepare a cooling action plan: the 2019 plan looks twenty years ahead and aims, by 2037-38, to cut cooling demand by 20-25 per cent, refrigerant demand by 25-30 per cent and cooling energy needs by 25-40 per cent, while training servicing technicians and treating ''thermal comfort for all'' as a development need. Cutting refrigerant demand also eases India''s path under the Montreal Protocol''s limits on climate-warming refrigerants.', explanation_hi = 'चारों कथन सही हैं। डिस्ट्रिक्ट कूलिंग नेटवर्क एक संयंत्र पर बड़े, दक्ष चिलर चलाकर ठंडा पानी ऊष्मारोधी पाइपों से दफ़्तरों, मॉल या आवास तक भेजता है, जिससे हज़ारों अलग इकाइयों की तुलना में बिजली की खपत और चरम भार घटता है; यह गिफ़्ट सिटी जैसे सघन नए विकासों के अनुकूल है, जहाँ ऐसा एक नेटवर्क है। भारत शीतलन कार्य योजना बनाने वाले पहले देशों में था: 2019 की योजना बीस वर्ष आगे देखती है और 2037-38 तक शीतलन माँग 20-25 प्रतिशत, प्रशीतक माँग 25-30 प्रतिशत और शीतलन ऊर्जा आवश्यकता 25-40 प्रतिशत घटाने का लक्ष्य रखती है, साथ ही सर्विस तकनीशियनों के प्रशिक्षण और ‘सबके लिए तापीय आराम’ को विकास की आवश्यकता मानती है। प्रशीतक माँग घटाना मॉन्ट्रियल प्रोटोकॉल के अंतर्गत जलवायु-तापक प्रशीतकों की सीमाओं की दिशा में भारत का मार्ग भी आसान करता है।', concept_group_id = 'ca-t1-env-district-cooling-icap-kigali', source_citation = 'Ministry of Environment, Forest and Climate Change, India Cooling Action Plan (March 2019).', question_data = '{"statements": ["The Plan also aims to reduce the demand for refrigerants by 25 to 30 per cent by 2037-38.", "The India Cooling Action Plan, released in 2019, aims to reduce cooling demand across sectors by 20 to 25 per cent by 2037-38.", "The Plan also aims to reduce the energy needed for cooling by 25 to 40 per cent by 2037-38.", "In district cooling, chilled water from a central plant is piped to many buildings instead of each building running its own air-conditioning plant."], "statements_hi": ["योजना का लक्ष्य 2037-38 तक प्रशीतकों की माँग 25 से 30 प्रतिशत घटाना भी है।", "2019 में जारी भारत शीतलन कार्य योजना का लक्ष्य 2037-38 तक सभी क्षेत्रों में शीतलन माँग 20 से 25 प्रतिशत घटाना है।", "योजना का लक्ष्य 2037-38 तक शीतलन के लिए आवश्यक ऊर्जा 25 से 40 प्रतिशत घटाना भी है।", "डिस्ट्रिक्ट कूलिंग में हर भवन के अपना वातानुकूलन संयंत्र चलाने के बजाय एक केंद्रीय संयंत्र से ठंडा पानी पाइपों द्वारा अनेक भवनों तक पहुँचाया जाता है।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true, "craft": "linkage", "ca_window": "2026-Q1"}'::jsonb, options = '[{"id": "a", "body": "1 and 2 only", "body_hi": "केवल 1 और 2", "isCorrect": false}, {"id": "b", "body": "1, 2, 3 and 4", "body_hi": "1, 2, 3 और 4", "isCorrect": true}, {"id": "c", "body": "1, 3 and 4 only", "body_hi": "केवल 1, 3 और 4", "isCorrect": false}, {"id": "d", "body": "2, 3 and 4 only", "body_hi": "केवल 2, 3 और 4", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'ca-t1-env-district-cooling-icap-kigali' returning concept_group_id;
update public.questions set subject = 'Environment & Ecology', topic = 'Flora, Fungi & Forests', type = 'statement_based', difficulty = 'medium', body = 'In January 2026 the Air Force was called in to fight a forest fire in the Valley of Flowers National Park. Consider the following statements:', body_hi = 'जनवरी 2026 में फूलों की घाटी राष्ट्रीय उद्यान में वन-अग्नि बुझाने के लिए वायु सेना बुलाई गई। निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Only statement 2 is correct. The Valley of Flowers, an alpine meadow in Chamoli district known for its summer bloom, is usually under snow and closed to visitors outside June to October. Statement 1 is wrong: with Nanda Devi National Park it forms the core of the Nanda Devi Biosphere Reserve in Uttarakhand; the Khangchendzonga Biosphere Reserve is in Sikkim. Statement 3 is wrong: Himalayan fires peak in the dry pre-monsoon months, roughly March to June, when pine needles and dry grass carry them. A fire raging for days in January was unusual, and was linked to a dry winter with little rain or snow from western disturbances.', explanation_hi = 'केवल कथन 2 सही है। चमोली ज़िले की अल्पाइन घाटी, फूलों की घाटी, जो अपने ग्रीष्मकालीन फूलों के लिए जानी जाती है, जून से अक्टूबर के बाहर प्रायः बर्फ़ से ढकी और पर्यटकों के लिए बंद रहती है। कथन 1 ग़लत है: नंदा देवी राष्ट्रीय उद्यान के साथ यह उत्तराखंड के नंदा देवी जैवमंडल आरक्षित क्षेत्र का कोर है; कंचनजंगा जैवमंडल आरक्षित क्षेत्र सिक्किम में है। कथन 3 ग़लत है: हिमालयी वन-अग्नि शुष्क मानसून-पूर्व महीनों, मोटे तौर पर मार्च से जून, में चरम पर होती है, जब चीड़ की पत्तियाँ और सूखी घास उसे फैलाती हैं। जनवरी में दिनों तक जलती आग असामान्य थी, और उसे पश्चिमी विक्षोभों से कम वर्षा या हिमपात वाली शुष्क सर्दी से जोड़ा गया।', concept_group_id = 'ca-t1-env-valley-of-flowers-winter-fire', source_citation = 'Forest Survey of India, India State of Forest Report (forest fire chapter); Ministry of Environment, Forest and Climate Change, list of Biosphere Reserves (Nanda Devi, Khangchendzonga); Uttarakhand Forest Department.', question_data = '{"statements": ["It forms a core zone of the Khangchendzonga Biosphere Reserve.", "The Valley of Flowers National Park lies in Chamoli district of Uttarakhand.", "In the Himalaya, forest fires are commonest in the winter months of December and January."], "statements_hi": ["यह कंचनजंगा जैवमंडल आरक्षित क्षेत्र का एक कोर क्षेत्र है।", "फूलों की घाटी राष्ट्रीय उद्यान उत्तराखंड के चमोली ज़िले में है।", "हिमालय में वन-अग्नि दिसंबर और जनवरी के शीतकालीन महीनों में सबसे आम होती है।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true, "craft": "inference", "ca_window": "2026-Q1"}'::jsonb, options = '[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "1 and 2 only", "body_hi": "केवल 1 और 2", "isCorrect": false}, {"id": "c", "body": "2 only", "body_hi": "केवल 2", "isCorrect": true}, {"id": "d", "body": "2 and 3 only", "body_hi": "केवल 2 और 3", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'ca-t1-env-valley-of-flowers-winter-fire' returning concept_group_id;
update public.questions set subject = 'Environment & Ecology', topic = 'Climate Agreements & Carbon Markets', type = 'statement_based', difficulty = 'medium', body = 'With reference to the UN climate conferences COP30 and COP31, consider the following statements:', body_hi = 'संयुक्त राष्ट्र जलवायु सम्मेलनों कॉप30 और कॉप31 के संदर्भ में, निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Both statements are correct. COP30 met at Belém in November 2025, the first COP held in the Amazon; COPs rotate among the five UN regional groups, and 2026 fell to the Western European and Others Group. Australia and Türkiye had both bid to host COP31; under a compromise reached at Belém, Türkiye hosts the conference at Antalya in November 2026 and holds the COP presidency, while Australia acts as ''President of Negotiations'' and hosts a pre-COP in the Pacific -- an unusual split that has itself drawn questions about who has the final say.', explanation_hi = 'दोनों कथन सही हैं। कॉप30 नवंबर 2025 में बेलेम में हुआ, अमेज़न में होने वाला पहला कॉप; कॉप संयुक्त राष्ट्र के पाँच क्षेत्रीय समूहों में बारी-बारी से जाते हैं, और 2026 पश्चिमी यूरोपीय और अन्य समूह की बारी थी। ऑस्ट्रेलिया और तुर्किये दोनों ने कॉप31 की मेज़बानी के लिए दावा किया था; बेलेम में हुए समझौते के अंतर्गत तुर्किये नवंबर 2026 में अंताल्या में सम्मेलन की मेज़बानी करता है और कॉप की अध्यक्षता रखता है, जबकि ऑस्ट्रेलिया ‘वार्ताओं का अध्यक्ष’ बनता है और प्रशांत क्षेत्र में एक प्री-कॉप की मेज़बानी करता है -- यह असामान्य बँटवारा स्वयं इस प्रश्न के घेरे में रहा है कि अंतिम निर्णय किसका होगा।', concept_group_id = 'ca-t1-env-cop30-tfff-cop31-turkiye-australia', source_citation = 'UNFCCC, decisions of COP30 (Belém, November 2025); Government of Australia, statement on COP31 arrangements (November 2025).', question_data = '{"statements": ["COP30 was held at Belém, in Brazil''s Amazon region.", "COP31, in 2026, is to be hosted by Türkiye, with Australia presiding over the negotiations."], "statements_hi": ["कॉप30 ब्राज़ील के अमेज़न क्षेत्र में बेलेम में हुआ।", "2026 में कॉप31 की मेज़बानी तुर्किये करेगा, और वार्ताओं की अध्यक्षता ऑस्ट्रेलिया करेगा।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true, "craft": "recall", "ca_window": "2026-Q1"}'::jsonb, options = '[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": true}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'ca-t1-env-cop30-tfff-cop31-turkiye-australia' returning concept_group_id;
update public.questions set subject = 'Environment & Ecology', topic = 'Ecosystems & Ecological Processes', type = 'statement_based', difficulty = 'easy', body = 'A warehouse fire in early 2026 drew attention to illegal construction on the East Kolkata Wetlands. Consider the following statements:', body_hi = '2026 के आरंभ में एक गोदाम में लगी आग ने पूर्वी कोलकाता आर्द्रभूमि पर अवैध निर्माण की ओर ध्यान खींचा। निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Statements 1 and 3 are correct. The East Kolkata Wetlands, a mosaic of sewage-fed fisheries, rice fields and garbage farms on the city''s eastern edge, became a Ramsar site in 2002 as an example of the ''wise use'' of a wetland: Kolkata''s wastewater flows into the bheris, where sunlight, algae and fish break down the organic load, so the city has avoided building a large sewage treatment plant while the wetlands supply fish and vegetables. Statement 2 is wrong: they are not a national park or sanctuary; they are protected under the East Kolkata Wetlands (Conservation and Management) Act, 2006 of West Bengal, administered by a management authority -- which has not stopped encroachment by real-estate and warehouse construction.', explanation_hi = 'कथन 1 और 3 सही हैं। शहर के पूर्वी किनारे पर सीवेज-पोषित मत्स्य पालन, धान के खेतों और कचरा-खेतों का मिश्रण, पूर्वी कोलकाता आर्द्रभूमि 2002 में आर्द्रभूमि के ‘विवेकपूर्ण उपयोग’ के उदाहरण के रूप में रामसर स्थल बनी: कोलकाता का अपशिष्ट जल भेरियों में बहता है, जहाँ सूर्य का प्रकाश, शैवाल और मछलियाँ जैविक भार को तोड़ देते हैं, इसलिए शहर ने बड़ा सीवेज उपचार संयंत्र बनाने से बचते हुए आर्द्रभूमि से मछली और सब्ज़ियाँ पाई हैं। कथन 2 ग़लत है: ये राष्ट्रीय उद्यान या अभयारण्य नहीं हैं; ये पश्चिम बंगाल के पूर्वी कोलकाता आर्द्रभूमि (संरक्षण और प्रबंधन) अधिनियम, 2006 के अंतर्गत एक प्रबंधन प्राधिकरण द्वारा संरक्षित हैं -- जो अचल-संपत्ति और गोदाम-निर्माण से अतिक्रमण नहीं रोक सका है।', concept_group_id = 'ca-t1-env-east-kolkata-wetlands-bheris', source_citation = 'Ramsar Sites Information Service, East Kolkata Wetlands (2002); East Kolkata Wetlands (Conservation and Management) Act, 2006 (West Bengal).', question_data = '{"statements": ["They treat much of the city''s sewage naturally, using it in fish ponds called bheris and in farming.", "They are protected as a national park under the Wild Life (Protection) Act, 1972.", "The East Kolkata Wetlands were designated a Ramsar site in 2002."], "statements_hi": ["ये शहर के अधिकांश सीवेज का प्राकृतिक उपचार करती हैं, उसे भेरी कहलाने वाले मत्स्य तालाबों और खेती में उपयोग करके।", "ये वन्यजीव (संरक्षण) अधिनियम, 1972 के अंतर्गत राष्ट्रीय उद्यान के रूप में संरक्षित हैं।", "पूर्वी कोलकाता आर्द्रभूमि को 2002 में रामसर स्थल घोषित किया गया।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true, "craft": "recall", "ca_window": "2026-Q1"}'::jsonb, options = '[{"id": "a", "body": "1 and 3 only", "body_hi": "केवल 1 और 3", "isCorrect": true}, {"id": "b", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "c", "body": "3 only", "body_hi": "केवल 3", "isCorrect": false}, {"id": "d", "body": "1, 2 and 3", "body_hi": "1, 2 और 3", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'ca-t1-env-east-kolkata-wetlands-bheris' returning concept_group_id;
commit;
